#include <bits/stdc++.h>

using namespace std;

using llong = long long;

const llong MOD = 1000000007LL;

inline tuple<llong, llong, llong> count_remainders(int l, int r) {
    return {
        r / 3 - (l - 1) / 3,
        (r + 2) / 3 - (l + 1) / 3,
        (r + 1) / 3 - l / 3
    };
}

void solve(int n, int l, int r) {
    vector<vector<llong>> dp(3, vector<llong>(n + 1, 0));
    dp[0][0] = 1;

    auto abc = count_remainders(l, r);
    llong counts[3] = {
        get<0>(abc),
        get<1>(abc),
        get<2>(abc)
    };

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < 3; ++j) {
            for (int k = 0; k < 3; ++k) {
                dp[(j + k) % 3][i + 1] += dp[j][i] * counts[k];
                dp[(j + k) % 3][i + 1] %= MOD;
            }
        }
    }

    cout << dp[0][n] << '\n';
}

int main() {
    int n, l, r;
    cin >> n >> l >> r;

    solve(n, l, r);

    return 0;
}

